'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let csrf='',hosts=[],selected='',page='overview',cfg={},toastTimer,modalRevision=0,releaseRequest=0,renderRevision=0,sessionRevision=0,currentUser=null;
const date=t=>t?new Date(t*1000).toLocaleString():'Not yet';
const badge=s=>`<span class="badge ${esc(s)}">${esc(s)}</span>`;
async function api(path,method='GET',body){const session=sessionRevision;const r=await fetch('/api'+path,{method,headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:body===undefined?undefined:JSON.stringify(body)});let data=await r.json();if(session!==sessionRevision&&path!=='/sso')throw Error('Session changed; previous response discarded');if(!r.ok){if(r.status===401)showLogin();throw Error(typeof data.detail==='string'?data.detail:JSON.stringify(data.detail));}return data;}
function toast(message){
 const target=$('#modal').open?$('#modal-message'):$('#toast');
 target.textContent=message;target.classList.remove('hidden');target.style.display='block';
 clearTimeout(toastTimer);toastTimer=setTimeout(()=>{target.style.display='none';},6000);
}
function showLogin(){
 sessionRevision++;renderRevision++;modalRevision++;releaseRequest++;
 csrf='';hosts=[];selected='';cfg={};currentUser=null;document.body.dataset.role='viewer';
 $('#modal').close();$('#modal-body').replaceChildren();$('#content').replaceChildren();
 $('#toast').style.display='none';clearTimeout(toastTimer);
 $('#login').classList.remove('hidden');$('#shell').classList.add('hidden');
}
function isAdmin(){return currentUser?.role==='admin';}
function currentView(revision,name){return revision===renderRevision&&page===name&&!$('#shell').classList.contains('hidden');}
function showShell(){$('#login').classList.add('hidden');$('#shell').classList.remove('hidden');}
function heading(title,sub,button=''){return `<div class="heading"><div><div class="eyebrow">FLEET CARE, UNDER CONTROL</div><h1>${title}</h1><p>${sub}</p></div>${button}</div>`;}
function empty(title,text,action=''){return `<div class="empty"><div class="empty-symbol">✚</div><h3>${title}</h3><p>${text}</p>${action}</div>`;}
function serverSelect(){return `<select id="server-select" aria-label="Select server">${hosts.map(h=>`<option value="${h.id}" ${h.id===selected?'selected':''}>${esc(h.name)}</option>`).join('')}</select>`;}
function hostName(id){return hosts.find(h=>h.id===id)?.name||id;}
function bindSelect(fn){$('#server-select')?.addEventListener('change',e=>{selected=e.target.value;fn().catch(error=>toast(error.message));});}
function modal(title,html){modalRevision++;$('#modal-message').classList.add('hidden');$('#modal-message').textContent='';$('#modal-title').textContent=title;$('#modal-body').innerHTML=html;$('#modal').showModal();}
async function render(){
 const revision=++renderRevision;
 let requested=location.hash.slice(1)||'overview';
 if(!['overview','servers','packages','repositories','investigations','activity','schedules','settings'].includes(requested))requested='overview';
 try{
  const [me,list]=await Promise.all([api('/identity'),api('/hosts')]);
  if(revision!==renderRevision)return;
  currentUser=me;document.body.dataset.role=me.role;hosts=list;
  if(!isAdmin()&&['settings','repositories','schedules'].includes(requested)){
   requested='overview';history.replaceState(null,'','#overview');
  }
  page=requested;
  document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===page);if(a.dataset.nav===page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
  $('#breadcrumb').textContent='Workspace / '+page[0].toUpperCase()+page.slice(1);
  if(!hosts.some(h=>h.id===selected))selected=hosts[0]?.id||'';
  $('#content').innerHTML='<p class="help" role="status">Loading…</p>';
  await ({overview,servers,packages,repositories,investigations,activity,schedules,settings}[page])(revision);
 }catch(error){if(revision===renderRevision)toast(error.message);}
}
async function overview(revision=renderRevision){const d=await api('/dashboard');if(!currentView(revision,'overview'))return;$('#content').innerHTML=heading('A healthier fleet starts here.','Your servers, packages, and security signals. One calm workspace.','<button class="primary" data-admin data-action="add">+ Add server</button>')+`<div class="stats"><div class="stat accent"><label>Connected servers</label><strong>${d.online}<small> / ${d.servers}</small></strong><small>Fresh telemetry, no integrity alerts</small></div><div class="stat"><label>Updates available</label><strong>${d.updates}</strong><small>Across ${d.packages.toLocaleString()} installed packages</small></div><div class="stat"><label>Past patch deadline</label><strong>${d.overdue}</strong><small>Based on your priority policy</small></div><div class="stat"><label>Integrity alerts</label><strong>${d.integrity_alerts}</strong><small>Managed files checked every 5 minutes</small></div></div><div class="grid"><section><div class="card"><div class="card-head"><h2>Your servers</h2><a href="#servers" class="mint">View all ↗</a></div>${hosts.length?hostTable(hosts.slice(0,5)):empty('Make room for your first server','Enroll a Debian, Ubuntu, Raspberry Pi OS, Fedora or DNF-based machine to start watching packages and processes.','<button data-admin data-action="add">Enroll a server →</button>')}</div><div class="hero"><div class="eyebrow">QUIETLY KEEPING WATCH</div><h2>Small checks.<br>A clearer picture.</h2><p>Repositories checked centrally every ${d.repo_minutes} minutes. Process activity sampled every 30 seconds. You decide what gets trusted and patched.</p><span class="cross">✚</span></div></section><section><div class="card"><h2>Your monitoring rhythm</h2><div class="timeline"><div><span class="step">01</span><section><h3>Collect &amp; compare</h3><p>Package inventory and signed repository metadata, resolved centrally.</p></section></div><div><span class="step">02</span><section><h3>Investigate the unfamiliar</h3><p>${d.investigations} behaviors awaiting your trust decision. AI triage is optional.</p></section></div><div><span class="step">03</span><section><h3>Patch with intention</h3><p>Review available versions and deadlines before installing selected updates.</p></section></div></div></div><div class="card"><h3>Trust is explicit.</h3><p class="help">Host keys are pinned. Repository signatures stay enforced. An AI opinion never automatically approves a process.</p><a data-admin href="#settings" class="mint">Review your policy →</a></div></section></div>`;}
function hostTable(rows){return `<div class="table-wrap"><table><thead><tr><th>Server</th><th>Status</th><th>Last seen</th><th></th></tr></thead><tbody>${rows.map(h=>`<tr><td><strong>${esc(h.name)}</strong><small>${esc(h.address)} · ${esc(h.architecture||'Awaiting enrollment')}</small></td><td>${badge(h.state)}</td><td>${date(h.last_seen)}</td><td><button data-action="inspect" data-id="${h.id}">${isAdmin()?'Manage':'Inspect'} ↗</button></td></tr>`).join('')}</tbody></table></div>`;}
async function servers(){$('#content').innerHTML=heading('Your Linux fleet.','Enroll, inspect, and care for every server.','<button class="primary" data-admin data-action="add">+ Add server</button>')+`<div class="card">${hosts.length?hostTable(hosts):empty('No servers enrolled yet','Start with a server name and SSH address. You can verify its fingerprint after running the installer.','<button class="primary" data-admin data-action="add">Add your first server</button>')}</div>`;}
async function addServer(){
 modal('Enroll server · Step 1 of 3',`<p class="help">Enter the endpoint Mr Patchy will reach over SSH.</p><form id="host-form"><div class="form-grid"><label>Display name<input name="name" placeholder="Living-room Pi" required maxlength="120"></label><label>IP address or hostname<input name="address" placeholder="192.168.1.50" required></label><label>SSH port<input type="number" name="port" value="22" min="1" max="65535"></label></div><button class="primary">Continue to preparation →</button></form>`);
 $('#host-form').onsubmit=async e=>{e.preventDefault();try{const b=Object.fromEntries(new FormData(e.target));b.port=+b.port;const r=await api('/hosts','POST',b);hosts=await api('/hosts');await prepareServer(r.id);}catch(e){toast(e.message);}};
}
async function prepareServer(id){
 const h=hosts.find(x=>x.id===id);
 modal('Prepare '+h.name+' · Step 2 of 3',`<p class="help">Run the script as root on <strong>${esc(h.address)}</strong>. Python 3, OpenSSH server, sudo and OpenSSL must already be installed. RPM targets also need python3-dnf and python3-rpm; SELinux systems need policycoreutils-python-utils. It creates /opt/drpatch, the drpatch user, a dedicated SSH public key and restricted sudo permissions. No network access is needed by the bootstrap.</p><label>Installation mode<select id="install-mode"><option value="curl">1 · Fetch from Mr Patchy with curl</option><option value="download">2 · Download and run on the target</option><option value="offline" selected>3 · Offline preparation, then finish over SSH</option></select></label><div id="install-delivery"><a href="/api/hosts/${id}/installer" download><button>↓ Download Bash installer</button></a><pre>sudo bash mrpatchy-enroll.sh</pre></div><p class="help">Keep the ED25519 SHA256 host fingerprint printed by the script. You will verify it in the next step.</p><button class="primary" id="prepare-next">I ran the script · Proceed to step 3 →</button>`);
 const delivery=$('#install-delivery'),mode=$('#install-mode'),revision=modalRevision;
 let requestNumber=0,selectedEndpoint='default';
 const current=number=>number===requestNumber&&revision===modalRevision&&delivery.isConnected&&mode.value==='curl';
 mode.onchange=async()=>{
  const number=++requestNumber;
  if(mode.value!=='curl'){
   delivery.innerHTML=`<a href="/api/hosts/${id}/installer" download><button>↓ Download Bash installer</button></a><pre>sudo bash mrpatchy-enroll.sh</pre>`;
   return;
  }
  delivery.innerHTML='<p class="help" role="status">Loading HTTPS endpoints…</p>';
  try{
   const {endpoints}=await api(`/hosts/${id}/enrollment-endpoints`);
   if(!current(number))return;
   delivery.innerHTML=`<label>Fetch from HTTPS endpoint<select id="install-endpoint">${endpoints.map(item=>`<option value="${esc(item.id)}">${esc(item.label)} · ${esc(item.url)}</option>`).join('')}</select></label><p class="help">Choose an address reachable from the target. Configure internal and external profiles in Settings → HTTPS.</p><div id="install-command"></div><p class="help">Link expires in one hour. If the target does not trust this endpoint's certificate, add --cacert /path/to/ca.pem to curl using a trusted CA bundle. The ACME directory URL is for certificate issuance, not installer downloads.</p>`;
   const endpoint=$('#install-endpoint'),command=$('#install-command');
   endpoint.value=endpoints.some(item=>item.id===selectedEndpoint)?selectedEndpoint:'default';
   endpoint.onchange=async()=>{
    const number=++requestNumber;
    selectedEndpoint=endpoint.value;
    command.innerHTML='<p class="help" role="status">Generating download link…</p>';
    try{
     const result=await api(`/hosts/${id}/enrollment-link`,'POST',{endpoint:selectedEndpoint});
     if(current(number)&&command.isConnected)command.innerHTML=`<pre>${esc(result.command)}</pre>`;
    }catch(error){if(current(number)){command.textContent='Unable to generate a link. Select an endpoint to retry.';toast(error.message);}}
   };
   await endpoint.onchange();
  }catch(error){if(current(number)){delivery.textContent='Unable to load HTTPS endpoints. Select the curl mode again to retry.';toast(error.message);}}
 };
 $('#prepare-next').onclick=()=>finishServer(id);
}
function finishServer(id){
 const h=hosts.find(x=>x.id===id);
 modal('Connect and verify · Step 3 of 3',`<p>Mr Patchy will connect to <strong>${esc(h.address)}:${h.port}</strong>, install its collector and service, then verify SHA-256 hashes, ownership, permissions and service state.</p><form id="finish-form"><label>ED25519 host fingerprint printed on the target<input name="fingerprint" value="${esc(h.fingerprint)}" placeholder="SHA256:…" required pattern="SHA256:[A-Za-z0-9+/]{43}"></label><p class="help">Verify this against the target console. SSH identity verification is required before connecting.</p><button class="primary">Finish and verify installation</button></form><div id="enrollment-result"></div>`);
 $('#finish-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button'),result=$('#enrollment-result');button.disabled=true;try{
  await api(`/hosts/${id}/fingerprint`,'PUT',{fingerprint:new FormData(e.target).get('fingerprint')});
  const job=await api(`/hosts/${id}/actions/deploy`,'POST');result.textContent='Queued. This page will show the verification result.';
  while(result.isConnected&&$('#modal').open){const state=await api('/jobs/'+job.job_id);result.textContent='Installation '+state.state+(state.output?' · '+state.output:'');if(['complete','failed','interrupted'].includes(state.state)){if(state.state==='complete'){result.textContent='Installation verified. Collector service is active; monitoring data will arrive shortly.';hosts=await api('/hosts');}break;}await new Promise(resolve=>setTimeout(resolve,2000));}
 }catch(error){result.textContent=error.message;}finally{button.disabled=false;}};
}
async function inspect(id){
 selected=id;const h=hosts.find(x=>x.id===id);
 modal(h.name,`<div class="toolbar">${badge(h.state)}<span class="muted">${esc(h.address)}:${h.port}</span></div>${h.error?`<div class="notice">${esc(h.error)}</div>`:''}<div data-admin><h3>Installation &amp; recovery</h3><p class="help">The personalized bootstrap is always available. Re-running it restores this server’s assigned public key and restricted helper.</p><div class="actions"><a href="/api/hosts/${id}/installer" download><button>↓ Download Bash installer</button></a><button id="resume-enrollment">Prepare / re-enroll</button><button id="finish-enrollment">Finish / verify installation</button></div></div><h3>Monitoring &amp; maintenance</h3><div class="actions"><button data-operator data-action="refresh" data-id="${id}">Check repositories</button><button data-admin id="host-history">Observation &amp; inventory history</button><button data-admin id="repair-packages">Repair broken package state</button><button data-admin id="release-upgrade" ${h.package_manager==='rpm'?'disabled title="RPM distribution upgrades are not supported yet"':''}>Plan distribution upgrade</button></div>${h.integrity.length?`<h3>Integrity findings</h3><pre>${esc(JSON.stringify(h.integrity,null,2))}</pre>`:''}`);
 $('#resume-enrollment').onclick=()=>prepareServer(id);$('#finish-enrollment').onclick=()=>finishServer(id);
 $('#host-history').onclick=()=>historyModal(id);
 $('#release-upgrade').onclick=()=>releasePanel(id);
 $('#repair-packages').onclick=()=>{modal('Review package recovery',`<p>${h.package_manager==='rpm'?'Rebuild and verify the RPM database':'Run dpkg configuration and APT dependency repair'} on <strong>${esc(h.name)}</strong>?</p><p class="help">${h.package_manager==='rpm'?'This verifies database structure only. Review dependency problems separately; no packages will be installed or removed.':'This can install dependencies and run maintainer scripts that restart services. Package removal is prohibited.'} Review the result in Activity before retrying a failed repair.</p><button class="primary" id="confirm-repair">Run recovery</button>`);$('#confirm-repair').onclick=async()=>{try{await api(`/hosts/${id}/actions/repair`,'POST');$('#modal').close();toast('Package recovery queued');}catch(e){toast(e.message);}};};
}
async function historyModal(id,kind='inventory',offset=0){
 const revision=modalRevision;try{const rows=await api(`/hosts/${id}/history?kind=${kind}&offset=${offset}&limit=20`);if(revision!==modalRevision)return;modal(hostName(id)+' · History',`<div class="actions"><button id="inventory-history">Inventory revisions</button><button id="observation-history">Process observations</button></div><p class="help">Retained according to your history policy. Observation timestamps are reported by the target.</p>${rows.map(r=>`<details class="source history-record" data-id="${r.id}"><summary>${date(r.created||r.observed)}</summary><pre>Loading details…</pre></details>`).join('')||'<p>No retained records.</p>'}<div class="actions"><button id="history-prev" ${offset?'':'disabled'}>Previous</button><button id="history-next" ${rows.length===20?'':'disabled'}>Next</button></div>`);document.querySelectorAll('.history-record').forEach(element=>element.addEventListener('toggle',async()=>{if(!element.open||element.dataset.loaded)return;try{const record=await api(`/hosts/${id}/history/${element.dataset.id}?kind=${kind}`);element.querySelector('pre').textContent=JSON.stringify(record.inventory||record.evidence,null,2);element.dataset.loaded='true';}catch(error){element.querySelector('pre').textContent=error.message;}}));$('#inventory-history').onclick=()=>historyModal(id,'inventory');$('#observation-history').onclick=()=>historyModal(id,'observations');$('#history-prev').onclick=()=>historyModal(id,kind,Math.max(0,offset-20));$('#history-next').onclick=()=>historyModal(id,kind,offset+20);}catch(e){toast(e.message);}
}
function recoverySummary(policy){return `<div class="notice"><strong>Approved recovery policy</strong><p>Automatic reboot: <strong>${policy.reboot?'enabled — services may be interrupted':'disabled'}</strong><br>Snapshot rollback: <strong>${policy.rollback?'enabled after a failed patch or post-reboot health check':'disabled'}</strong></p><small>Changing this policy before execution requires a new patch approval.</small></div>`;}
async function packages(){const hostId=selected;if(!selected){$('#content').innerHTML=heading('Packages, accounted for.','Installed versions and centrally discovered updates.')+empty('Enroll a server first','Package inventory appears after the collector is installed.');return;}$('#content').innerHTML=heading('Packages, accounted for.','Candidates come from central APT / DNF repository checks. Held and version-locked packages stay protected.')+`<div class="toolbar">${serverSelect()}<input id="package-search" aria-label="Find a package" placeholder="Find a package…"><label class="check"><input id="updates-only" type="checkbox"> Updates only</label><button class="primary" data-operator id="patch-selected">Install selected updates</button></div><div class="card" id="package-table"></div>`;bindSelect(packages);let timer,requestNumber=0;const table=$('#package-table');const load=async()=>{if(selected!==hostId||!table.isConnected)return;const request=++requestNumber;const rows=await api(`/hosts/${hostId}/packages?q=${encodeURIComponent($('#package-search').value)}&updates=${$('#updates-only').checked}`);if(request!==requestNumber||selected!==hostId||!table.isConnected)return;table.innerHTML=rows.length?`<div class="table-wrap"><table><thead><tr><th></th><th>Package</th><th>Installed / state</th><th>Candidate</th><th>Priority</th><th>Deadline</th></tr></thead><tbody>${rows.map(p=>`<tr><td><input type="checkbox" class="pkg-check" aria-label="Select ${esc(p.name)}" data-version="${esc(p.candidate)}" value="${esc(p.name)}" ${currentUser?.role==='viewer'||!p.candidate||p.held||(p.dpkg_state&&!p.dpkg_state.endsWith(' installed'))?'disabled':''}></td><td>${esc(p.name)}${p.held?'<small>Held by target policy</small>':''}</td><td>${esc((p.installed_versions||[p.installed]).join(', '))}<small>${esc(p.dpkg_state||'install ok installed')}</small></td><td>${esc(p.candidate||'—')}</td><td>${p.candidate?`<select ${isAdmin()?'':'disabled'} class="priority-select" data-name="${esc(p.name)}" aria-label="Patch priority">${['auto','critical','high','normal','low'].map(v=>`<option value="${v}" ${v===(p.priority_manual?p.priority:'auto')?'selected':''}>${v==='auto'?'Auto ('+p.priority+')':v}</option>`).join('')}</select>`:'—'}</td><td>${p.due?date(p.due):'—'}</td></tr>`).join('')}</tbody></table></div>`:empty('No matching packages','Finish enrollment and check repositories to populate the inventory.');};$('#package-table').addEventListener('change',async e=>{if(!e.target.matches('.priority-select'))return;try{await api(`/hosts/${hostId}/priority`,'PUT',{name:e.target.dataset.name,priority:e.target.value});toast('Patch priority saved');await load();}catch(error){toast(error.message);}});$('#package-search').oninput=()=>{clearTimeout(timer);timer=setTimeout(()=>load().catch(e=>toast(e.message)),250);};$('#updates-only').onchange=()=>load().catch(e=>toast(e.message));$('#patch-selected').onclick=async()=>{const chosen=[...table.querySelectorAll('.pkg-check:checked')];const names=chosen.map(x=>x.value);const expected_versions=Object.fromEntries(chosen.map(x=>[x.value,x.dataset.version]));if(!names.length)return toast('Select at least one available update');let policy;try{policy=await api(`/hosts/${hostId}/patch-policy`);}catch(error){return toast(error.message);}if(selected!==hostId||!table.isConnected)return;modal('Review patch installation',`<p>Install the selected updates on <strong>${esc(hostName(hostId))}</strong>?</p><p class="help">Package scripts may restart services. Package removal and held-package upgrades are prohibited.</p>${recoverySummary(policy)}<pre>${esc(names.join('\n'))}</pre><button class="primary" id="confirm-patch">Install ${names.length} selected updates</button>`);$('#confirm-patch').onclick=async event=>{const button=event.target;button.disabled=true;try{await api(`/hosts/${hostId}/patch`,'POST',{packages:names,expected_versions,expected_recovery_policy:policy});$('#modal').close();toast('Installation queued. Follow progress in Activity.');}catch(e){toast(e.message);button.disabled=false;}};};await load();}
async function repositories(revision=renderRevision){const hostId=selected;if(!selected){$('#content').innerHTML=heading('Repositories, in view.','Every configured source, with its original format preserved.')+empty('No repository inventory yet','Enroll a server to view and manage its sources.');return;}const r=await api(`/hosts/${hostId}/repositories`),rpm=r.package_manager==='rpm',editable=path=>r.editable_paths?r.editable_paths.includes(path):!path.includes('preferences');if(selected!==hostId||!currentView(revision,'repositories'))return;$('#content').innerHTML=heading('Repositories, in view.','Edit sources, repair URLs, manage suites and signing keys.')+`<div class="toolbar">${serverSelect()}<div class="actions"><button data-operator data-action="refresh" data-id="${hostId}">↻ Check now</button><button id="new-source">+ Add source</button><button id="upload-key">Upload signing key</button><button id="repository-access">Repository access</button><button id="restore-backup">Restore backup</button></div></div><div class="card"><div class="card-head"><h2>Source configuration</h2><small>Last successful check: ${date(r.last_checked)}</small></div>${r.error?`<div class="notice">${esc(r.error)}</div>`:''}<p class="help">Changes are backed up on the target. Disable a Deb822 stanza with Enabled: no, a .repo section with enabled=0, comment a .list line, or save an empty file to remove its repositories. A failed refresh never marks stale metadata as current.</p><div class="toolbar">${(r.health||[]).map(x=>`<span title="${esc(x.detail)}">${esc(x.path.split('/').pop())} ${badge(x.state)}</span>`).join('')}</div><div id="source-files">${Object.entries(r.files).map(([path,content])=>`<details class="source"><summary>${esc(path)}</summary><textarea data-path="${esc(path)}" ${!editable(path)?'readonly':''}>${esc(content)}</textarea>${editable(path)?'<button class="save-source">Review &amp; save</button>':'<p class="help">Package-manager policy is mirrored centrally. Edit this policy on the target.</p>'}</details>`).join('')||'<p class="muted">Awaiting inventory.</p>'}</div></div><div class="card"><h2>Discovered signing keys</h2><pre>${esc(r.keys.join('\n')||'No keys discovered')}</pre><p class="help">${rpm?'RPM keys are imported into the target RPM trust database. Set gpgkey=file:///etc/pki/rpm-gpg/your-key.asc in the .repo file.':'For rotated keys, upload a replacement and point the repository’s Signed-By setting at /etc/apt/keyrings/your-key.asc.'}</p></div>`;bindSelect(repositories);$('#repository-access').onclick=()=>repositoryAccessModal(hostId);$('#restore-backup').onclick=()=>backupModal(hostId);document.querySelectorAll('.save-source').forEach(btn=>btn.onclick=()=>{const ta=btn.previousElementSibling;saveSource(ta.dataset.path,ta.value,hostId);});$('#new-source').onclick=()=>{modal('Add repository source',`<form id="new-source-form"><label>Path<input name="path" value="${rpm?'/etc/yum.repos.d/custom.repo':'/etc/apt/sources.list.d/custom.sources'}" required></label><label>Source configuration<textarea name="content" placeholder="${rpm?'[vendor]&#10;name=Vendor&#10;baseurl=https://example.org/rpm/$releasever/$basearch&#10;enabled=1&#10;gpgcheck=1&#10;gpgkey=file:///etc/pki/rpm-gpg/vendor.asc':'Types: deb&#10;URIs: https://example.org/debian&#10;Suites: stable&#10;Components: main&#10;Signed-By: /etc/apt/keyrings/vendor.asc'}" required></textarea></label><button class="primary">Review source</button></form>`);$('#new-source-form').onsubmit=e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target));$('#modal').close();saveSource(b.path,b.content,hostId);};};$('#upload-key').onclick=()=>{modal('Upload repository signing key',`<p class="help">Verify the key fingerprint with the repository publisher before uploading. ${rpm?'RPM keys are imported into the system RPM trust database and can validate packages from any configured RPM repository.':'It will only be trusted by repositories referencing it through Signed-By.'}</p><form id="key-form"><label>Key file (.asc or .gpg)<input name="key" type="file" accept=".asc,.gpg" required></label><button class="primary">Upload key to target</button></form>`);$('#key-form').onsubmit=async e=>{e.preventDefault();try{const f=e.target.key.files[0];const bytes=new Uint8Array(await f.arrayBuffer());let raw='';for(const b of bytes)raw+=String.fromCharCode(b);await api(`/hosts/${hostId}/keys`,'PUT',{name:f.name,data:btoa(raw)});$('#modal').close();toast('Key upload queued');}catch(e){toast(e.message);}};};}
function saveSource(path,content,hostId){modal('Review repository change',`<p class="help">Write this configuration to ${esc(hostName(hostId))}. Existing content is backed up under /opt/drpatch/backups.</p><h3>${esc(path)}</h3><pre>${esc(content||'(empty file — repositories disabled)')}</pre><button class="primary" id="confirm-source">Save to target</button>`);$('#confirm-source').onclick=async()=>{try{await api(`/hosts/${hostId}/repositories`,'PUT',{path,content});$('#modal').close();toast('Repository change queued');}catch(e){toast(e.message);}};}
async function investigations(revision=renderRevision){const [rows,status]=await Promise.all([api('/investigations'),api('/investigation-status')]);if(!currentView(revision,'investigations'))return;$('#content').innerHTML=heading('A second look at the unfamiliar.','Host-specific executable hashes, identities, and connection patterns.')+`<div class="notice">Queue: ${status.pending} pending · ${status.hourly_limit}/hour · ${status.enabled?'enabled':'disabled'}. Oldest pending: ${date(status.oldest)}. AI assessments are advisory. A known-good approval applies only to this exact executable hash, user, and connection pattern on this host. Changed behavior creates a new investigation.</div>`+(rows.length?rows.map(r=>`<div class="card investigation"><div><div class="eyebrow">${esc(hostName(r.host_id))}</div><h3><code>${esc(r.evidence.executable)}</code></h3><p class="help">UID ${esc(r.evidence.uid)} · Last seen ${date(r.last_seen)}</p>${badge(r.approved?'approved':r.verdict)}</div><button data-admin data-action="trust" data-id="${r.id}" data-approved="${r.approved}">${r.approved?'Revoke approval':'Review & approve'}</button><div class="description">${esc(r.analysis)}</div><details><summary>Evidence &amp; SHA-256</summary><pre>${esc(JSON.stringify(r.evidence,null,2))}</pre></details></div>`).join(''):empty('Nothing to investigate yet','New executable hashes and connection patterns appear here after a server starts reporting.'));}
async function activity(revision=renderRevision){
 const me=await api('/identity'),[jobs,audit]=await Promise.all([api('/jobs'),me.role==='admin'?api('/audit'):Promise.resolve([])]);
 if(!currentView(revision,'activity'))return;
 $('#content').innerHTML=heading('A record of the work.','Queued operations, results, and recovery decisions.')+`<div class="card"><h2>Operations</h2>${jobs.length?jobs.map(j=>`<details class="source"><summary>${badge(j.state)} ${esc(j.action)} · ${esc(hostName(j.host_id))} · ${date(j.created)}</summary><pre>${esc(j.output||'Awaiting execution')}</pre>${me.role==='admin'&&j.state==='queued'?`<button class="cancel-job" data-id="${j.id}">Cancel queued operation</button>`:''}${me.role==='admin'&&['running','recovery_required'].includes(j.state)?`<button class="reconcile-job" data-id="${j.id}">Review interrupted operation</button>`:''}</details>`).join(''):empty('No operations yet','Enrollment, repository checks, and patch runs will appear here.')}</div>${me.role==='admin'?`<div class="card"><h2>Audit trail</h2><div class="table-wrap"><table><thead><tr><th>When</th><th>Action</th><th>Detail</th></tr></thead><tbody>${audit.map(a=>`<tr><td>${date(a.created)}</td><td>${esc(a.action)}</td><td>${esc(a.detail)}</td></tr>`).join('')}</tbody></table></div></div>`:''}`;
 document.querySelectorAll('.cancel-job').forEach(button=>button.onclick=()=>{modal('Cancel queued operation',`<p>Cancel this operation before it starts? A linked release plan will also be cancelled and require a new plan.</p><button class="primary" id="confirm-cancel-job">Cancel operation</button>`);$('#confirm-cancel-job').onclick=async event=>{event.target.disabled=true;try{await api('/operations/jobs/'+button.dataset.id+'/cancel','POST');$('#modal').close();await activity();toast('Operation cancelled');}catch(error){toast(error.message);event.target.disabled=false;}};});
 document.querySelectorAll('.reconcile-job').forEach(button=>button.onclick=()=>{
  modal('Reconcile interrupted operation',`<p>Verify package state, services, reboot status and any snapshot rollback on the target through a trusted console first. Check for a pending reboot timer. This releases the host’s queue; it does not retry the interrupted operation.</p><p class="help">Mr Patchy also requires both the central worker lock and target mutation lock to be idle.</p><form id="reconcile-form"><label class="check"><input type="checkbox" required>I verified the target state and it is safe to resume queued work</label><button class="primary">Reconcile and release queue</button></form>`);
  $('#reconcile-form').onsubmit=async e=>{e.preventDefault();try{await api('/operations/jobs/'+button.dataset.id+'/reconcile','POST',{verified_target_state:true});$('#modal').close();await activity();}catch(error){toast(error.message);}};
 });
}
async function settings(revision=renderRevision){const settingsData=await api('/settings');if(!currentView(revision,'settings'))return;cfg=settingsData;$('#content').innerHTML=heading('Set your own rhythm.','Patch deadlines, investigation policy, and secure access.')+`<form id="settings-form"><div class="grid"><div><div class="card"><h2>Patch policy</h2><p class="help">Deadlines begin when a candidate version is first discovered. Security-origin updates default to high; other updates default to normal. These are scheduling priorities, not CVSS scores. Deadlines flag overdue work; they do not trigger unattended installation.</p><div class="form-grid">${['critical','high','normal','low'].map(k=>`<label>${k[0].toUpperCase()+k.slice(1)} · hours<input name="${k}" type="number" min="1" max="8760" value="${cfg.deadlines[k]}" required></label>`).join('')}</div><label>Repository check interval · minutes<input name="repo_minutes" type="number" min="5" max="10080" value="${cfg.repo_minutes}" required></label><p class="help">Target process sampling: 30 seconds. Full managed-file and executable hash refresh: 5 minutes.</p></div><div class="card"><h2>AI investigations</h2><label class="check"><input name="ai_enabled" type="checkbox" ${cfg.ai_enabled?'checked':''}>Enable central OpenAI API investigations</label><p class="help">Sends executable paths, SHA-256 hashes, UIDs, and network endpoint metadata to OpenAI. Investigations can request fixed read-only package ownership, executable metadata and systemd service properties. Command-line arguments, environment variables, and arbitrary file contents are excluded. Each investigation uses up to two model calls. Responses use store: false; your API organization’s data policies still apply.</p><label>Model ID<input name="ai_model" value="${esc(cfg.ai_model)}" placeholder="Enter a Responses API model you have access to"></label><label>API key ${cfg.api_key_configured?'· configured':''}<input name="api_key" type="password" autocomplete="new-password" placeholder="Leave blank to keep the existing key"></label><label>Maximum investigations per hour<input name="ai_hourly_limit" type="number" min="1" max="1000" value="${cfg.ai_hourly_limit}"></label><p class="help">Save changes before testing. The test sends one small request to OpenAI using the saved model and key; no server evidence is included. Failed investigations retry after a one-hour backoff.</p><button type="button" id="ai-test">Test saved AI settings</button><p id="ai-test-result" class="help" role="status"></p></div><button class="primary">Save monitoring settings</button></div><div><div class="card"><h2>HTTPS &amp; certificates</h2><p class="help">Independent internal and external profiles support uploaded certificates, Let's Encrypt, custom ACME and the built-in local CA.</p><p>${Object.entries(cfg.tls.profiles||{}).filter(([,p])=>p.enabled).map(([name,p])=>esc(name+': '+p.domain)+' · '+badge(p.mode)).join('<br>')||'Initial HTTPS configured by deployment'}</p><button type="button" id="tls-button">Configure HTTPS →</button></div><div class="card"><h2>History retention</h2><label>Days to retain observations and inventory revisions<input name="history_days" type="number" min="1" max="3650" value="${cfg.history_days||30}"></label><h2>Data stays with your deployment.</h2><p class="help">SQLite is the default. MySQL is supported through DATABASE_URL. Back up the database and persistent app volume together, including SSH identities and the encryption key.</p><p class="help">Each target gets its own SSH key. The target makes no outbound connection to Mr Patchy or OpenAI.</p></div></div></div></form>`;$('#settings-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),body={repo_minutes:+f.get('repo_minutes'),deadlines:Object.fromEntries(['critical','high','normal','low'].map(k=>[k,+f.get(k)])),history_days:+f.get('history_days'),ai_enabled:f.has('ai_enabled'),ai_model:f.get('ai_model'),api_key:f.get('api_key'),ai_hourly_limit:+f.get('ai_hourly_limit')};try{await api('/settings','PUT',body);toast('Monitoring settings saved');}catch(e){toast(e.message);}};$('#ai-test').onclick=async event=>{const button=event.currentTarget,result=$('#ai-test-result');button.disabled=true;result.textContent='Testing saved AI settings…';try{const response=await api('/settings/ai-test','POST');if(currentView(revision,'settings')&&result.isConnected)result.textContent=response.detail;}catch(error){if(currentView(revision,'settings')&&result.isConnected)result.textContent=error.message;}finally{if(button.isConnected)button.disabled=false;}};$('#tls-button').onclick=tlsModal;}
async function tlsModal(){
 const revision=modalRevision;let state;
 try{state=await api('/tls');}catch(error){toast(error.message);return;}
 if(revision!==modalRevision)return;
 modal('Internal & external HTTPS',`<p class="help">Two independent certificate profiles share the published HTTPS listener. Use different hostnames; certificate selection follows the hostname requested by your browser. Internal is a certificate profile, not a network access restriction.</p><label>Profile<select id="tls-profile"><option value="internal">Internal</option><option value="external">External / public</option></select></label><div id="tls-profile-editor"></div>`);
 const editor=$('#tls-profile-editor');
 const draw=()=>{
  const profile=$('#tls-profile').value,item=state.profiles[profile];
  editor.innerHTML=`<form id="tls-form"><label class="check"><input name="enabled" type="checkbox" ${item.enabled?'checked':''}>Enable this HTTPS profile</label><label>Domain or IP address<input name="domain" value="${esc(item.domain)}" placeholder="${profile==='internal'?'patchy.home.example.com':'patchy.example.com'}"></label><label>Additional hostnames (one per line)<textarea name="aliases">${esc((item.aliases||[]).join('\n'))}</textarea></label><div class="form-grid"><label>Browser-facing HTTPS port<input name="https_port" type="number" min="1" max="65535" value="${item.https_port||''}" placeholder="Docker HTTPS_PORT (${item.effective_https_port})"></label><label class="check"><input name="redirect_http" type="checkbox" ${item.redirect_http?'checked':''}>Redirect HTTP to this profile's HTTPS address</label></div><label>Certificate mode<select name="mode"><option value="internal">Built-in local CA</option><option value="acme">ACME (Let's Encrypt or custom CA)</option><option value="uploaded">Upload certificate &amp; private key</option></select></label><div id="tls-acme"><label>ACME directory URL<input name="acme_url" type="url" value="${esc(item.acme_url)}" placeholder="https://acme-v02.api.letsencrypt.org/directory"></label><label>ACME account email<input name="email" type="email" value="${esc(item.email)}"></label><label>Challenge method<select name="challenge"><option value="auto">Automatic (HTTP-01 / TLS-ALPN-01)</option><option value="http">HTTP-01 only</option><option value="tlsalpn">TLS-ALPN-01 only</option></select></label><label>ACME server CA bundle ${item.ca_configured?'· configured':''}<input type="file" name="ca" accept=".pem,.crt"></label><label class="check"><input name="clear_ca" type="checkbox">Clear saved CA bundle (use system trust)</label><label>EAB key ID (optional)<input name="eab_id" value="${esc(item.eab_id)}"></label><label>EAB HMAC key ${item.eab_configured?'· configured':''}<input name="eab_key" type="password" autocomplete="new-password" placeholder="Leave blank to keep the saved secret"></label><label class="check"><input name="clear_eab" type="checkbox">Clear saved EAB credentials</label></div><div id="tls-upload"><p class="help">${item.certificate_configured?'A certificate and key are saved. Leave uploads empty to keep them.':'Upload a certificate chain and its matching unencrypted private key.'} The SAN must cover every hostname in this profile.</p><div class="form-grid"><label>Certificate chain PEM<input type="file" name="certificate" accept=".pem,.crt"></label><label>Private key PEM<input type="file" name="private_key" accept=".pem,.key"></label></div></div><p class="help">Public ACME still needs external TCP 80 and/or 443 forwarded to the published Docker ports. Use the port override only when the browser-facing port differs from HTTPS_PORT. Keep PUBLIC_URL aligned with your default enrollment/SSO address. Curl enrollment also lets you select either enabled HTTPS profile. Changing addresses may require signing in again.</p><button class="primary">Validate &amp; apply this profile</button></form>`;
  const form=$('#tls-form'),selector=$('#tls-profile');
  form.elements.mode.value=item.mode;form.elements.challenge.value=item.challenge;
  const modeChanged=()=>{$('#tls-acme').classList.toggle('hidden',form.elements.mode.value!=='acme');$('#tls-upload').classList.toggle('hidden',form.elements.mode.value!=='uploaded');};
  form.elements.mode.onchange=modeChanged;modeChanged();
  form.onsubmit=async event=>{
   event.preventDefault();const f=new FormData(form),button=form.querySelector('button');button.disabled=true;selector.disabled=true;
   const body={enabled:f.has('enabled'),domain:f.get('domain').trim(),aliases:f.get('aliases').split(/\s+/).filter(Boolean),mode:f.get('mode'),acme_url:f.get('acme_url'),email:f.get('email'),https_port:f.get('https_port')?+f.get('https_port'):null,redirect_http:f.has('redirect_http'),challenge:f.get('challenge'),eab_id:f.get('eab_id'),eab_key:f.get('eab_key'),clear_ca:f.has('clear_ca'),clear_eab:f.has('clear_eab')};
   try{
    for(const key of ['ca','certificate','private_key']){const file=f.get(key);if(file.size>100000)throw Error('Each PEM upload must be at most 100 KB');body[key]=file.size?await file.text():'';}
    const saved=await api('/tls/'+profile,'PUT',body);if(!form.isConnected)return;
    state=saved;cfg.tls=saved;draw();toast('HTTPS profile applied. Certificate issuance may continue in the background.');
   }catch(error){if(form.isConnected)toast(error.message);}finally{if(button.isConnected)button.disabled=false;if(selector.isConnected)selector.disabled=false;}
  };
  $('#modal').scrollTop=0;
 };
 $('#tls-profile').onchange=draw;draw();
}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const {action,id}=b.dataset;try{if(action==='add')return addServer();if(action==='inspect')return inspect(id);if(['deploy','refresh'].includes(action)){await api(`/hosts/${id}/actions/${action}`,'POST');toast('Operation queued. See Activity for progress.');return;}if(action==='trust'){const approved=b.dataset.approved!=='true';modal(approved?'Approve known-good behavior':'Revoke behavior approval',`<p>${approved?'Record this exact behavior as reviewed and trusted? Its AI assessment alone is not proof of safety.':'This behavior will no longer be marked as trusted.'}</p><button class="primary" id="confirm-trust">${approved?'Approve behavior':'Revoke approval'}</button>`);$('#confirm-trust').onclick=async()=>{try{await api('/investigations/'+id,'PUT',{approved});$('#modal').close();await investigations();}catch(e){toast(e.message);}};}}catch(e){toast(e.message);}});
